import crypto from 'node:crypto';import fs from 'node:fs';import path from 'node:path';import {PDFDocument,StandardFonts} from 'pdf-lib';
export const CLIENTS={ALPHA:{clientId:'client-alpha',clientName:'Alpha Academy LLC',workspaceId:'ws-alpha-bulk',engagementId:'eng-alpha-bulk'},BETA:{clientId:'client-beta',clientName:'Beta Academy LLC',workspaceId:'ws-beta-bulk',engagementId:'eng-beta-bulk'}} as const;export const SHARED_VALUE=84.20;export const SHARED_PERIOD='FY 2026';export const SHARED_LABEL='Office Supplies';
export function isolationDir(){return process.env.CLIENT_ISOLATION_ACCEPTANCE_DIR||'/tmp/eve-client-isolation';}export const sha256=(b:Buffer)=>crypto.createHash('sha256').update(b).digest('hex');
export function clientDir(which:'ALPHA'|'BETA'){return path.join(isolationDir(),which.toLowerCase());}
export function csvBytes(which:'ALPHA'|'BETA'){const c=CLIENTS[which];return Buffer.from(`Client,Period,Account,Amount,Currency\n${c.clientName},${SHARED_PERIOD},${SHARED_LABEL},${SHARED_VALUE.toFixed(2)},USD\n`,'utf8');}
export async function pdfBytes(which:'ALPHA'|'BETA'){const c=CLIENTS[which],doc=await PDFDocument.create();doc.setTitle('Expense Support');doc.setAuthor('Eve Academy');doc.setCreator('Eve Academy Fixture Generator');doc.setProducer('Eve Academy Fixture Generator');doc.setCreationDate(new Date('2026-09-16T00:00:00Z'));doc.setModificationDate(new Date('2026-09-16T00:00:00Z'));const page=doc.addPage([612,792]),font=await doc.embedFont(StandardFonts.Helvetica);page.drawText(`${c.clientName} | ${SHARED_PERIOD} | ${SHARED_LABEL} | USD ${SHARED_VALUE.toFixed(2)}`,{x:72,y:700,size:14,font});return Buffer.from(await doc.save({useObjectStreams:false,addDefaultPage:false}));}
export function load(which:'ALPHA'|'BETA',name:'general-ledger.csv'|'expense-support.pdf'){return fs.readFileSync(path.join(clientDir(which),name));}
